const d = $input.first().json;
const kind = String(d.kind || '').trim();
let p = {};
try { p = (typeof d.payload === 'string') ? JSON.parse(d.payload) : (d.payload || {}); } catch (e) { p = {}; }
if (typeof p !== 'object' || p === null || Array.isArray(p)) p = {};
const conf = d.confirmed === true || d.confirmed === 'true' || d.confirmed === 1;
const B = d.bot_id, U = d.user_id;
const nn = v => (v === undefined || v === '' ? null : v);
let query, params, label;
if (kind === 'allergen') {
  if (!p.substance) throw new Error('allergen без substance');
  query = 'INSERT INTO allergen (bot_id,user_id,substance,severity,confirmed) VALUES ($1,$2,$3,$4,$5) RETURNING id';
  params = [B, U, String(p.substance).trim(), (p.severity === 'intolerance' ? 'intolerance' : 'allergy'), conf];
  label = 'аллерген: ' + p.substance + ' (' + (p.severity === 'intolerance' ? 'непереносимость' : 'аллергия') + ')';
} else if (kind === 'preference') {
  if (!p.item) throw new Error('preference без item');
  query = 'INSERT INTO food_preference (bot_id,user_id,item,stance) VALUES ($1,$2,$3,$4) RETURNING id';
  params = [B, U, String(p.item).trim(), (p.stance === 'dislike' ? 'dislike' : 'like')];
  label = 'предпочтение: ' + p.item + ' (' + (p.stance === 'dislike' ? 'не любит' : 'любит') + ')';
} else if (kind === 'condition') {
  if (!p.name) throw new Error('condition без name');
  query = 'INSERT INTO condition (bot_id,user_id,name,since,confirmed) VALUES ($1,$2,$3,$4::date,$5) RETURNING id';
  params = [B, U, String(p.name).trim(), nn(p.since), conf];
  label = 'состояние: ' + p.name;
} else if (kind === 'injury') {
  if (!p.area) throw new Error('injury без area');
  const st = ['active','rehab','resolved'].includes(p.status) ? p.status : 'active';
  query = 'INSERT INTO injury (bot_id,user_id,area,status,since,confirmed) VALUES ($1,$2,$3,$4,$5::date,$6) RETURNING id';
  params = [B, U, String(p.area).trim(), st, nn(p.since), conf];
  label = 'травма: ' + p.area + ' (' + st + ')';
} else if (kind === 'medication') {
  if (!p.name) throw new Error('medication без name');
  query = 'INSERT INTO medication (bot_id,user_id,name,dose,schedule,reason,started_on,confirmed) VALUES ($1,$2,$3,$4,$5,$6,$7::date,$8) RETURNING id';
  params = [B, U, String(p.name).trim(), nn(p.dose), nn(p.schedule), nn(p.reason), nn(p.started_on), conf];
  label = 'препарат: ' + p.name;
} else {
  throw new Error('неизвестный kind: ' + kind);
}
return [{ json: { query, params, label, confirmed: conf } }];
